"use strict";
// A logging helper whose loader picks its part with a computed require()
// specifier: scriptc cannot compile that natively, so the package runs in
// a Node island and the program's console crosses into it.
const { createRequire } = require("node:module");
const load = createRequire(__filename);
const [use] = ["./lib/use"].map((p) => load(p));

exports.useLogger = use.useLogger;
exports.callFn = use.callFn;
exports.isConsole = use.isConsole;
exports.describe = use.describe;
exports.useUntyped = use.useUntyped;
